package com.campusnova.service; import com.campusnova.knowledge.RetrievalResult; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CollegeRelevanceService { private final SemanticTextService semantic; public CollegeRelevanceService(SemanticTextService s){semantic=s;} public boolean isCollegeRelated(String question,RetrievalResult retrieval,Collection<String> memory){if(retrieval.getConfidence()>=.12)return true;Set<String> words=semantic.terms(question);String[] institutional={"college","campus","student","semester","course","subject","faculty","department","office","id","card","form","policy","workshop","seminar","academic","notice"};for(String w:institutional)if(words.contains(w))return true;return !memory.isEmpty()&&question.trim().split("\\s+").length<10;} }
